import static org.junit.Assert.assertTrue;

public class LocaleUtils_isAvailableLocale_TriageGen4Test {

    @Test
    public void testIsAvailableLocale_WithAvailableLocale() {
        // Retrieve the actual available locales from the utility itself to ensure a valid positive case
        Set<Locale> availableLocales = LocaleUtils.availableLocaleSet();
        if (!availableLocales.isEmpty()) {
            Locale availableLocale = availableLocales.iterator().next();
            assertTrue("Expected locale " + availableLocale + " to be available", 
                LocaleUtils.isAvailableLocale(availableLocale));
        }
    }






}

