package org.apache.commons.lang;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class LocaleUtils_isAvailableLocale_TriageGen4Test {







    @Test
    public void testIsAvailableLocale_WithCommonLocales() {
        // Test specific common locales to check consistency
        // Note: Availability depends on the JVM environment, but we test the logic flow
        Locale us = Locale.US;
        Locale gb = Locale.UK;

        // We don't assert true/false strictly because the set is environment dependent,
        // but we exercise the branch for these common objects.
        boolean resultUs = LocaleUtils.isAvailableLocale(us);
        boolean resultGb = LocaleUtils.isAvailableLocale(gb);

        // If they are available, they must return true. If not, false. 
        // This ensures no exceptions are thrown during standard lookup.
        if (LocaleUtils.availableLocaleSet().contains(us)) {
            assertTrue(LocaleUtils.isAvailableLocale(us));
        }
        if (LocaleUtils.availableLocaleSet().contains(gb)) {
            assertTrue(LocaleUtils.isAvailableLocale(gb));
        }
    }
}
